.modal-overlay.show{opacity:1;pointer-events:auto;}
.modal{background:var(--bg-card);border:1px solid var(--gold);border-radius:12px;padding:24px;width:340px;box-shadow:0 10px 40px rgba(0,0,0,0.5);transform:translateY(20px);transition:transform 0.3s;}
.modal-overlay.show .modal{transform:translateY(0);}
.modal-title{font-size:17px;font-weight:700;color:var(--red);margin-bottom:12px;text-transform:uppercase;letter-spacing:1px;}
.modal textarea{width:100%;height:80px;background:var(--bg-dark);border:1px solid var(--border);border-radius:8px;color:var(--text-main);padding:10px;font-family:inherit;font-size:15px;resize:none;outline:none;margin-bottom:16px;}
.modal textarea:focus{border-color:var(--red);}
.input-password{width:100%;padding:10px;border-radius:8px;border:1px solid var(--border);background:var(--bg-dark);color:var(--text-main);font-size:17px;outline:none;margin-bottom:16px;text-align:center;letter-spacing:2px;}
.input-password:focus{border-color:var(--gold);}
.modal-actions{display:flex;justify-content:flex-end;gap:10px;}
.modal-btn{padding:8px 16px;border-radius:6px;font-size:15px;font-weight:700;cursor:pointer;border:none;}
.modal-btn.cancel{background:var(--bg-row-odd);color:var(--text-muted);border:1px solid var(--border);}
.modal-btn.confirm{background:var(--red-dim);color:var(--red);border:1px solid var(--red);}
tfoot td{background:var(--bg-header);color:var(--gold);font-weight:800;padding:10px 8px;border-top:2px solid var(--gold);font-size:15px;}
.custom-tooltip{position:fixed;display:none;z-index:999999;pointer-events:none;background:linear-gradient(135deg,#13192f 0%,#090d1a 100%);color:#e8eaf0;border:1px solid var(--gold);border-radius:8px;padding:8px 12px;font-size:12px;line-height:1.4;box-shadow:0 12px 32px rgba(0,0,0,0.8),0 0 15px rgba(212,175,55,0.25);opacity:0;transform:translateY(4px);transition:opacity 0.15s ease,transform 0.15s ease;max-width:260px;}
.custom-tooltip.show{display:block;opacity:1;transform:translateY(0);}
.custom-tooltip .tt-header{display:flex;align-items:center;gap:5px;font-size:11px;font-weight:700;color:var(--gold-bright);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:4px;border-bottom:1px solid rgba(212,175,55,0.2);padding-bottom:3px;}
.custom-tooltip .tt-body{font-size:12px;color:var(--text-main);font-weight:500;}
@keyframes fadeIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:translateY(0);}}
tbody tr{animation:fadeIn 0.25s ease forwards;}
</style>"

