                        if (saved.dataPgtoRepasse !== undefined) rawData[i].dataPgtoRepasse = saved.dataPgtoRepasse;
                    }
                } else if (!rawData[i].status || rawData[i].status === '') rawData[i].status = 'Pendente';
            }
            renderTable();
        }
    })
    .catch(function(e){ console.log('Servidor offline'); });
}
