            payload[String(r.id)] = { status: r.status, motivo: r.motivo || '', nfCliente: r.nfCliente || '', obsNfCliente: r.obsNfCliente || '', dataAprovacao: r.dataAprovacao || '', dataNfCliente: r.dataNfCliente || '', dataPgtoRepasse: r.dataPgtoRepasse || '' };
